function plan({ templates, inbox, now, templateProject, inboxProject }) {
  if (!templateProject || !inboxProject || templateProject === inboxProject)
    throw Error("Template and Inbox projects must differ");
  const date = new Date(now);
  if (!Number.isFinite(date.getTime())) throw Error("Invalid run date");
  const weekday = ["sun", "mon", "tues", "wed", "thurs", "fri", "sat"][date.getUTCDay()];
  const remove = [];
  for (const t of inbox.tasks) {
    if (!t || typeof t.id !== "string" || !t.id || !Array.isArray(t.labels))
      throw Error("Invalid Inbox task");
    if (t.labels.includes("daily")) remove.push(t.id);
  }
  const create = [];
  for (const t of templates.tasks) {
    if (
      !t ||
      typeof t.id !== "string" ||
      !t.id ||
      typeof t.content !== "string" ||
      !t.content ||
      typeof t.description !== "string"
    )
      throw Error("Invalid template task");
    const fields = {};
    for (const part of t.description.split(";")) {
      const p = part.trim().split(":");
      if (p.length === 2) fields[p[0]] = p[1].trim();
    }
    if (!(fields.days || "").includes(weekday)) continue;
    let dueDatetime;
    if (fields.due) {
      const m = /^(\d{1,2})(?:\.(\d{2}))?([ap]m)$/i.exec(fields.due);
      if (!m || +m[1] < 1 || +m[1] > 12 || +(m[2] || 0) > 59)
        throw Error("Invalid template due time");
      let h = (+m[1] % 12) + (m[3].toLowerCase() === "pm" ? 12 : 0);
      const d = new Date(date);
      d.setUTCHours(h, +(m[2] || 0), 0, 0);
      dueDatetime = d.toISOString();
    }
    create.push({
      content: t.content,
      description: t.description,
      ...(dueDatetime ? { dueDatetime } : {}),
    });
  }
  return { remove, create };
}

const valid = (x) =>
  x.flatMap((y) => {
    const v = y.json;
    if (!v || typeof v !== "object" || Array.isArray(v)) throw Error("Invalid task");
    if (!Object.keys(v).length) return [];
    if (typeof v.id !== "string" || !v.id) throw Error("Task is missing its ID");
    return [v];
  });
const p = plan({
