  inbox: { tasks: valid($input.all()) },
  now: new Date().toISOString(),
  templateProject: $("Read template tasks").params.filters.projectId,
  inboxProject: $("Read Inbox tasks").params.filters.projectId,
});
return [{ json: p }];

